def aplicar(funcion, valor):
    """Ejecuta funcion sobre valor y devuelve el resultado."""
    return funcion(valor)


print(aplicar(abs, -7))
print(aplicar(lambda x: x ** 2, 6))
print(aplicar(str.upper, "hola"))

def aplanar(lista):
    """Devuelve una lista plana con todos los elementos anidados."""
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado


datos = [1, [2, 3], [4, [5, 6]]]
print(aplanar(datos))

def factorial(n):
    if n == 1:
        return 1
    return n * factorial(n - 1)


print(factorial(3))

